('SEG-2026-000001','PROSPECT','Prospect','Signed up but no completed purchase before the snapshot.','RFM','LIFECYCLE_VALUE',1,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'ACTIVE','2026-01-01',NULL),
('SEG-2026-000002','NEW_CUSTOMER','New customer','First purchase within the last 60 days.','RFM','LIFECYCLE_VALUE',2,NULL,NULL,1,NULL,NULL,NULL,60,NULL,NULL,NULL,NULL,1,'ACTIVE','2026-01-01',NULL),
('SEG-2026-000003','CHAMPIONS','Champions','Bought recently, often and with high net spend (R>=4, F>=4, M>=4).','RFM','LIFECYCLE_VALUE',3,4,NULL,4,NULL,4,NULL,NULL,NULL,NULL,NULL,NULL,1,'ACTIVE','2026-01-01',NULL),
('SEG-2026-000004','LOYAL','Loyal','Recent and repeat buyers (R>=3, F>=3).','RFM','LIFECYCLE_VALUE',4,3,NULL,3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'ACTIVE','2026-01-01',NULL),
('SEG-2026-000005','POTENTIAL_LOYALIST','Potential loyalist','Recent buyers with few orders so far (R>=3).','RFM','LIFECYCLE_VALUE',5,3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'ACTIVE','2026-01-01',NULL),
('SEG-2026-000006','AT_RISK','At risk','Last purchase 121-240 days ago (R=2).','RFM','LIFECYCLE_VALUE',6,2,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'ACTIVE','2026-01-01',NULL),
